    interpretation: "班超之业，成于汉廷国力为后盾，而见于个人胆略。其初使西域，所将不过三十六人，能在鄯善逆转局面，靠的是对匈奴使团人数、鄯善王心理的精准判断，与置之死地而后生的决断。西域诸国在汉与匈奴之间首鼠两端，班超深谙其理，故以少击众、以夷制夷，借于阗、疏勒之兵破莎车、龟兹，借西域之力供养西域之战。永元二年月氏七万之众东来，班超断其粮道、设伏斩使，不战而屈人之兵，说明其用兵重后勤、重心理而非恃勇。其长远影响在于重通丝路，五十余国内属使东汉边防推至葱岭之外，甘英之行更留下中原人对西方的最早记载。班超之后，其子班勇再定西域，班氏父子相承，为汉廷守西陲近半个世纪。",
