    summary: "东汉永平十六年（73），班超以假司马从窦固出击北匈奴，旋奉命率三十六人出使西域。他夜袭匈奴营于鄯善，逼降于阗、疏勒，以寡兵孤悬绝域三十一年。其间历明帝之丧、都护陈睦见杀，退守而复进；其后却贵霜七万之兵，平莎车、龟兹、焉耆，永元三年（91）任西域都护，永元六年（94）使西域五十余国悉纳质内属，自王莽以来断绝的西域重归汉廷。永元九年遣甘英抵条支、临西海；永元十四年病逝洛阳。",
    background: "西汉末，王莽改制，贬易西域诸王，诸国怨叛，匈奴乘虚复入西域，汉与西域遂绝。东汉初年，光武帝以天下初定，无暇外事，西域诸国累遣使请置都护，皆不许。然匈奴复盛，赋敛诸国，南道诸国苦之。永平十六年（73），明帝欲遵武帝故事，击匈奴、通西域，乃大发兵：奉车都尉窦固出酒泉，至天山，击北匈奴呼衍王，斩首千余级，追至蒲类海，取伊吾卢地，置宜禾都尉屯田。伊吾乃西域门户、匈奴资粮所出，汉得之，匈奴势衰。班超，扶风平陵人，班彪少子，兄班固、妹班昭皆史学家。少时为官佣书，尝投笔叹曰：「大丈夫无他志略，犹当效傅介子、张骞立功异域，以取封侯，安能久事笔研间乎？」后为兰台令史，坐事免官，乃从军为窦固假司马，战于蒲类海，多有斩获，遂受命出使西域。",
