          "永元十二年（100），班超年近七十，久在绝域，上书求归，辞甚悲切；其妹班昭亦上书代请，和帝览而感之，乃征还。永元十四年（102）八月，班超至洛阳，拜射声校尉，九月卒，年七十一。任尚代为都护，班超戒之曰：「水清无大鱼，察政不得下和，宜宽小过，总大纲。」任尚不能用，其后西域果叛，汉复弃都护，益见班超抚御之难继。"
