    interpretation: "班超之成功，非恃汉兵之众，而恃地缘之明：匈奴据北、汉通南，南道诸国苦匈奴赋敛久矣，班超因势利导，以夷制夷，借于阗、疏勒之兵破姑墨、莎车，以三十六人起家而终成五十余国之臣服。其经营西域，复通都护，丝路再畅，汉之使节商旅得越葱岭而抵安息、条支，甘英之行更将汉人地理认知推至波斯湾。然班超一去，任尚严急，西域旋叛，汉复弃之，愈见班超抚御之难及。三十一年孤悬绝域，身系西域安危，此其所以为后世所追慕。",
