          "在纸普及之前，欧洲以羊皮为书，一部圣经需杀羊数百，知识为教会贵族所垄断。廉价的纸与后世的印刷术相辅相成，书籍成本骤降，平民读书识字成为可能。蔡伦所改进的造纸术，与印刷术、火药、指南针并称四大发明，其影响远超汉家宫阙。从树皮麻缕到文明载体，其间相隔的，是千年的流泽。"
