    interpretation: "察举制的深层逻辑，是以乡里评议为国家选官基础：朝廷承认地方社会对人物的品评，再以举荐方式将其纳入官僚体系。这一设计在汉初打破了先秦世卿世禄与秦代文吏政治，使布衣可以至公卿，公孙弘以牧豕之身对策拜相，即为其明证。但其根本缺陷在于评价权不在国家手里：举主决定谁被举荐，被举者对举主负责胜过对朝廷负责，二者结为私恩，久而久之选举必为世家大族垄断。左雄以考试夺回评价权，方向正确，然门阀根基已成，积重难返。察举制的失败说明，选拔人才必须有独立、客观、可监督的标准——这正是后世科举制以考试取代推荐的历史逻辑所在。",
