          "至汉营，经故人魏无知引见，刘邦与语大悦，即拜都尉、参乘、典护军。诸将不服，周勃、灌婴等谗于汉王曰：「平虽美丈夫，如冠玉耳，其中未必有也。」又言其居家盗嫂、事魏事楚皆不终、今为护军受诸将金。汉王以责无知，无知答以所用者才，苟利于国家，私行何足计。陈平遂自陈：「项王不能信人，其所任爱，非诸项即妻之昆弟，虽有奇士不能用，闻汉王能用人，故归大王。臣裸身来，不受金无以为资。」汉王乃谢，厚赐之，拜护军中尉，尽护诸将，诸将乃不敢复言。"
