          "汉三年（前204年），楚汉相持于荥阳，汉军数困。陈平献反间计，言于刘邦：「项王骨鲠之臣，唯亚父范增、钟离昧、龙且、周殷之属数人耳，若能捐金行间，疑其君臣，破楚必矣。」汉王乃出黄金四万斤，恣平所为，不问出入。平多以金纵反间于楚军，宣言钟离昧等欲与汉连和，项羽果疑之。楚使至汉，平先具太牢之食，见使者佯惊曰：「吾以为亚父使者，乃项王使者。」复撤去，以恶草具进。使者归报，项王乃大疑范增，范增怒而请归，未至彭城，疽发背而死。楚之谋主既失，胜负之势渐移。",
