          "高祖末年，有人毁樊哙党于吕氏。高祖怒，使陈平与周勃即军中斩哙。平私谓勃曰：哙，吕后妹夫也，帝在怒中，我等若斩之，他日必悔。遂定计执哙，传诣长安，平自驰归。行未至，高祖已崩，平奔丧宫中，吕后哀之，释樊哙。惠帝六年（前189年），相国曹参薨，王陵为右丞相，陈平为左丞相。吕后欲立诸吕为王，问陵，陵曰不可；问平，平曰可。王陵怒责平，平曰：「于今面折廷争，臣不如君；全社稷，定刘氏之后，君亦不如臣。」吕后乃废王陵，徙平为右丞相，审食其为左丞相。",
          "高后八年（前180年）七月，吕后崩，诸吕欲为乱。陈平与太尉周勃合谋，先得周勃入北军之机；使郦寄绐吕禄交出将印，周勃遂入北军，号令「为吕氏右袒，为刘氏左袒」，军中皆左袒，遂诛吕产、吕禄等，悉夷诸吕，迎代王刘恒即位，是为文帝。文帝元年（前179年），平以周勃功高，让右丞相，自为左丞相，居顷之，勃自知不能，谢病免，平乃专为丞相。文帝二年（前178年）十月，陈平卒，谥献侯。平尝自叹：「我多阴谋，是道家之所忌，吾世即废亦已矣。」后曾孙陈何坐略人妻弃市，国除，果如其言。"
