    interpretation: "陈平佐高祖定天下、又安刘氏于吕氏之乱，历四朝而善终，司马迁称其「善始善终」，非偶然。其计或行反间、或厚赂、或伪游，皆乘人之隙，不拘常理，太史公论曰「常出奇计，救纷纠之急，振国家之患」。观荥阳夜遁、白登解围，皆于绝境中别开生面；其诛诸吕，则隐忍待时，非一味用险。平之所以能然，在于识势：知项羽之不可事、知吕氏之终败、知功臣当让，黄老因应之风，于其一身见之。汉初布衣将相之局，平以一介贫士终为贤相，亦时代之产物。然其自叹「多阴祸」，知阴谋不可长恃，其后国除，竟验于此言，此其智之深、亦其虑之远也。",
