    summary: "秦朝灭亡后，西楚霸王项羽分封十八路诸侯，将刘邦封为汉王，逐入巴蜀汉中。汉元年（前206年），刘邦拜韩信为大将军，明修栈道、暗度陈仓，迅速还定三秦，随即东出与项羽争夺天下。此后近五年间，双方历经彭城惨败、荥阳成皋相持、韩信破赵下齐等数十战。汉五年（前202年），刘邦会合韩信、彭越、英布等部合围垓下，项羽兵败突围，自刎于乌江。楚汉之争以刘邦全胜告终，汉朝由此建立，开启四百余年大一统王朝，奠定了此后中国政治制度的基本格局。",
    background: "秦二世三年（前207年），刘邦率先入关，秦王子婴出降，秦朝灭亡。项羽率四十万诸侯联军随后入关，驻军鸿门，实力远在刘邦之上。汉元年（前206年）正月，项羽自立为西楚霸王，都彭城，分封十八路诸侯。刘邦被压制到偏远险恶的巴蜀，封为汉王，都南郑；秦降将章邯、司马欣、董翳分封关中，号为三秦，用以阻塞刘邦东归之路。项羽分封大失公允，所封非亲即故，未获封地的田荣率先在齐地反楚，陈馀驱逐赵王张耳，彭越横行梁地，燕王韩广被臧荼所杀，天下初定即复大乱。刘邦采纳萧何之策，烧绝栈道以示无东还之意，麻痹项羽；又听从萧何推荐拜韩信为大将军，整军经武，等待东出时机。",
