          "平定关中后，刘邦留兵围困废丘，随即大举东进。汉二年（前205年）三月，汉军从临晋渡河，迫降河南王申阳、韩王郑昌，魏王豹率兵相从；又南渡平阴津攻殷，俘虏殷王司马卬。此时项羽正陷于齐地泥潭：田荣自立为齐王，项羽亲率大军北上讨伐，「坑田荣降卒，系虏其老弱」，齐地反抗愈烈，楚军主力被牢牢牵制。刘邦趁机纠集常山王张耳等五路诸侯，号称五十六万大军，于汉二年四月一举攻占项羽都城彭城。"
