          "其后公孙弘位至丞相，嫉仲舒之能，乃荐于武帝，以为可相胶西王刘端。胶西王闻仲舒大儒，善待之。仲舒在国，正身率下，数上疏谏争，匡君止过，皆本《春秋》之义；然惧久居获罪，在职数岁，告病免归。归居之后，终不问家产业，惟以修学著书为事。朝廷遇有大议，武帝常使使者及廷尉张汤就其家问之，仲舒所对皆合经术明法，虽在野而见重如此。"
