          "仲舒著述，《汉书》本传记其「皆明经术之意，及上疏条教，凡百二十三篇；而说《春秋》事得失，《闻举》《玉杯》《繁露》《清明》《竹林》之属，数十篇，十余万言」。今传《春秋繁露》八十二篇，乃后人辑录，间有附益，然大体存其本真。其书以《公羊春秋》为纲，融阴阳五行于儒术，系统阐发天人感应、王道三纲、通三统、张三世之说；《郊祀》《求雨》《止雨》诸篇，可见其以阴阳推步为用。",
          "仲舒之学，又开「春秋决狱」一脉。廷尉张汤数以疑狱就问，仲舒据《春秋》经旨以断，后儒辑为《春秋决事比》，以经术缘饰律令，汉法遂成外儒内法之局。元朔五年（前124），武帝从公孙弘之议，为五经博士置弟子员五十人，复其身，太学由此而立；察举取士渐以经术为本，通经致用成为入仕正途。自元光对策至此不过十年，儒学已自百家之一跃为国家法定之学。",
