    interpretation: "董仲舒的历史地位，不在仕途显赫——他终身不过藩国之相、中大夫——而在其以一套天人宇宙论为儒学争得国家意识形态之位。秦以法家立国而速亡，汉初以黄老休养而趋治；至武帝时国力既充，外事匈奴、内强集权，皆需一统之理据。仲舒对策，以天人感应赋予君权神圣性，又以灾异之说约束君权；以大一统论证集权，以五常涵养纲纪；更请屏退百家，自制度上断绝异学进身之路。武帝遂立五经博士、置弟子员、开太学、以经术取士，儒学与利禄正式挂钩，士人靡然向学。其流弊则是思想定于一尊，渐成禁锢，谶纬附会亦由此而生；然两千年间儒学正统之所以维系，其制度化起点实在于此。",
