          "袁绍乃献策，请召四方猛将引兵入京，以兵威迫太后从命。主簿陈琳进谏，以为「掩目捕雀，尚惧不得」，若委兵权于外臣，必生乱阶；何进一概不听，发诏召并州牧董卓将兵诣京，又遣府掾王匡、骑都尉鲍信还本州募兵。何进弟河南尹何苗素受宦官厚贿，从中阻挠，太后愈持两端。何进本握天下之权，却舍近求远，以兵柄授于人，京师安危自此不可问。",
