          "卓惮山东兵盛，二月乃挟献帝迁都长安，驱洛阳民数百万口入关，步骑驱蹙，积尸盈路。卓自留屯毕圭苑，纵火焚烧洛阳宫庙、官府、民家，二百里内无复孑遗；复令吕布发诸帝陵及公卿冢墓，收其金宝。百年帝都，化作焦土。初平二年（191年），卓自号太师，位在诸侯王上，筑郿坞于郿县，坞高厚七丈，积谷可支三十年，珍宝山积，卓自言「事成，雄据天下；不成，守此足以毕老」，其志在代汉，已昭然若揭。"
