    interpretation: "董卓之乱是东汉崩溃的枢纽，其根源在于皇权弱化之后权力制衡的全面失效。灵帝既崩，外戚、宦官、士人、边将四股势力失衡：何进召外兵诛宦官，本欲借边镇之兵，实为引狼入室，将朝廷最后的武力筹码拱手让与军阀。董卓以凉州兵威行废立，开「兵强马壮者当为之」之先例，天子由天下共主沦为强臣手中的器具。迁都焚洛，毁掉的不只是百年帝都，更是中央权威的象征与根基。关东联军名为讨董，实则各怀异志、相互兼并，迅速蜕变为军阀混战。故董卓虽诛，汉室已不可复兴：州牧制度使地方军政合流，割据格局由此固化，历史从王朝衰亡正式转入群雄逐鹿的三国时代。",
