          "建安四年夏，袁绍简精兵十万、骑兵万匹，以审配、逢纪统军事，田丰、荀谌、许攸为谋主，颜良、文丑为将帅，准备南下攻许。田丰、沮授皆力谏，以为曹操善用兵，未可轻视，宜以持久之计困之；袁绍不纳。建安五年（200年）正月，董承等衣带诏事泄，伏诛；其时刘备已杀徐州刺史车胄，占据下邳，与袁绍遥相呼应。田丰劝袁绍乘曹操东征刘备之机，直袭许都，袁绍辞以幼子有病，拒不发兵。田丰举杖击地长叹：『夫遭难遇之机，而以婴儿病失之，惜哉！』袁绍闻之怒，将其械系下狱。战机一失，胜负之数已悄然逆转。"
