          "袁绍怒而渡河追击，命骑将文丑与刘备率五六千骑兵追击曹军。曹操麾下此时骑兵不满六百，部将皆惧。曹操令士卒解鞍放马，又将辎重粮草弃置于道，佯作慌乱溃逃之状。文丑骑兵追至，争相抢夺辎重，阵势大乱；曹操乘势纵骑突击，大破之，斩文丑。颜良、文丑皆为河北名将，两月之间相继被杀，袁军锐气大挫，士气由盛转衰。曹操以寡击众，两战皆捷，为官渡决战赢得了先机；袁绍虽折损二将，十万之众犹在，遂合力压向官渡。"
