          "曹操回师官渡，合力进击，袁军十万之众一夜溃散，四散奔逃。袁绍与长子袁谭来不及披甲，仅率八百余骑仓皇渡河北逃，辎重、图书、珍宝尽为曹军所获。据《三国志》记载，袁军余众伪降，被曹操尽数坑杀，前后所杀及受降者达七万余人。战后曹操清点缴获，发现许都朝臣及曹军将士与袁绍暗中往来的书信无数，一律焚毁，不予追究，并说：『当绍之强，孤亦不能自保，况众人乎！』此举安定了军心人心，亦显其驾驭众人之术。历时数月的官渡之战，遂以曹操全胜告终。"
