    interpretation: "韩信之死，是军事天才与政治短板错配的极致。他用兵善造奇正，背水结阵、壅水半渡、垓下合围，皆以少胜多、以众克寡的典范，将冷兵器时代的战争艺术推至高峰，刘邦自承「连百万之军，战必胜，攻必取，吾不如韩信」。然而他政治上近乎天真：灭齐后乘刘邦危急求封齐王，已触皇权大忌；被贬之后仍怨望形于颜色，终授吕后以口实。就大局而言，汉初异姓王与皇权天然不相容，刘邦立国后逐一剪除，韩王信、彭越、英布次第覆灭，韩信之死并非孤例。能决胜沙场者未必善处庙堂，功高震主而不知自全，这便是韩信留给后世最深的一课。",
