    summary: "《汉书》一百篇，东汉班固承父班彪之业纂成，为中国第一部纪传体断代史。记事起汉高祖元年（前206），讫王莽地皇四年（23），凡西汉二百三十年。全书分十二本纪、八表、十志、七十列传，体例严整，文辞赡雅，与《史记》并称「史汉」。班固死于狱中，八表与《天文志》由其妹班昭奉诏续成。书成后注家蜂起，唐颜师古注最称善本，后世列为正史第二，与《史记》《后汉书》《三国志》合称「前四史」。",
    background: "西汉自高祖开基，经文景之治、汉武盛世，国祚逾二百年，制度文物粲然大备。司马迁著《史记》，止于汉武帝太初、天汉之际，其后诸事阙然。汉室尊崇儒术，朝廷有修史之意，而私家亦有续补之志。班彪字叔皮，扶风安陵人，仕于光武之世，以《史记》自太初以后阙而不录，乃作《史记后传》数十篇，斟酌前史，笔削未就而卒。其子班固年少博学，诵习父书，慨然有继述之志。时东汉朝廷正重国史之业，私家著述易触法禁，班固因此遭狱祸，亦因此得奉诏修书，此书遂由私撰转为官修，开后世正史之先河。",
    chapters: [
      {
        heading: "承家学而续史记",
        paragraphs: [
          "班固字孟坚，扶风安陵人，生于东汉光武帝建武八年（公元32年）。其父班彪，字叔皮，当两汉之际，以才学显于世。班彪以《史记》自太初以后阙而不录，乃作《史记后传》数十篇，斟酌去取，欲成一代之典。班固年九岁能属文，十六岁入太学，博览群书，而于父书讽诵尤勤，慨然有继述之志。",
          "建武三十年（公元54年），班彪卒，班固自太学还乡守制。居丧之中，检校父稿，以《史记》通贯古今而止于武帝，汉事多阙，遂立志踵事增华，别创新体。其书断代为史，专记西汉，起高祖，讫王莽，与父书之意一脉相承，而体例、断限皆为更张。此汉史之大业，实肇基于班彪，而成于班固之手。"
        ]
      },
      {
        heading: "遭狱祸而奉明诏",
        paragraphs: [
          "永平五年（公元62年），有人上书告班固私改国史，郡吏捕之，入京兆狱。其弟班超惧兄不测，驰赴阙下，上书陈情，具言班固著书之意在颂扬汉德，非有谤讪。明帝览其书而奇之，下诏召班固至洛阳。事白，拜为兰台令史，与前睢阳令陈宗、长陵令尹敏、司隶从事孟异共成《世祖本纪》。",
          "帝嘉其才，乃命续成前书。班固奉诏，专精积思，历二十余年。兰台为汉室典籍秘府，班固居其职，尽窥中秘之书，得天独厚。至建初七年（公元82年），全书大体告成，凡百篇。班固自述其志，欲使一代典制，综其行事，旁贯五经，上下洽通，传之无穷。由私家著述而为朝廷之命，此书之地位遂定。"
        ]
      },
      {
        heading: "断代为书创百篇",
        paragraphs: [
          "《汉书》一百篇，约八十余万言，分十二本纪、八表、十志、七十列传。本纪自高祖至平帝，帝王在位，编年记事；表以系年月，王侯将相，粲然可考；志分律历、礼乐、刑法、食货、郊祀、天文、五行、地理、沟洫、艺文十篇，典章制度，巨细无遗；列传载将相名臣、循吏儒林、外戚佞幸、匈奴西域，包举一代人物。",
          "其书断代为史，专记西汉二百三十年事，首标一朝之终始。视《史记》之通贯古今，别为一格。汉以前史，或为编年，或为纪传通史，未有专记一朝者；班固创之，遂为后世正史不易之体。自《后汉书》以下，历代修史，皆以断代为准，迄于《明史》，莫之能改。",
          "十志尤为独造。《地理志》详郡县户口、山川物产；《食货志》述农桑钱币、货殖之制；《艺文志》为现存最早之图书目录，考先秦学术之源流；《匈奴传》叙边疆民族之兴衰。皆后世正史诸志之权舆，其于典章、学术、地理之价值，或出于本纪、列传之上。"
        ]
      },
      {
        heading: "妹续书而书成学显",
        paragraphs: [
          "永元四年（公元92年），外戚窦宪以谋逆伏诛，班固曾为宪幕属，株连入狱，旋死于狱中，年六十一岁。其时《汉书》大体已成，而八表与《天文志》尚未就。和帝乃诏其妹班昭，令就东观藏书阁续成之。班昭字惠班，一名姬，同郡曹世叔之妻，博学高才，奉诏踵成八表，又助撰《天文志》，全书乃克成功。",
          "书成，因多用古字古训，时人多不能读。同郡马融伏于东观阁下，从班昭受读，其书乃行。自是《汉书》大显，列于学官。后世注解数十家，最著者为唐颜师古注，汇集诸说，最为善本；清王先谦《汉书补注》又集其成。与《史记》《后汉书》《三国志》合称「前四史」，治汉史者莫不以为典要。",
          "唐代以《汉书》与《史记》《后汉书》列为「三史」，设科取士，天下士子肄习其书，由是「汉书学」大兴，几与经学比隆。注家代出，著录于《隋书·经籍志》者已有数十家，班固之书，遂为后世史籍之轨范。"
        ]
      }
    ],
    interpretation: "《汉书》之要在断代，在正统。汉以前史家或记言，或记事，或为通史；班固乃断代为书，专记一朝，此后历朝正史，自《后汉书》至《明史》，皆沿其体，未有能出其外者。其书尊崇汉室，以汉为正统，于王莽则置于传末，贬为「贼莽」，此正统之辨，实为后世史家所本。然班固亦失之拘谨：删《史记》之讥刺，去「世家」之名，于汉室多有隐讳，致有「文赡而事详，然蔽于正统」之讥。要之，《汉书》兼具文献与文章之美，上承太史公，下启百代史官，为中国史籍之第二大经典。",
