      {
        heading: "身死国除，其书长存",
        paragraphs: [
          "元狩元年（前122年），刘安谋反事发，武帝遣使穷治其狱，王自刭而死，国除为九江郡，坐死宗族宾客数千人，伍被、雷被皆预其事。淮南国自高祖十一年（前196年）立国，历三世四王而绝。然《淮南子》未以人废，仍藏秘府，行于民间。东汉之世，许慎、高诱先后为之作注，许注今残，高注二十一卷独全，为现存最早注本，此后传习不绝。",
          "魏晋以降，其书代有传刻。北宋有刻本行世，明清刊本尤多，士子诵习，文家取资。唐宋大诗人如李白、苏轼，集中女娲补天、嫦娥奔月、共工触山之典，往往见于此书；后人治诸子之学，亦以其为杂家之宗而重之。清乾隆间修《四库全书》，收入子部杂家类，为古代子书之要籍。书虽成于诸侯王邸，而流播天下，非一时一地之物。",
          "今日观之，其书之价值尤在保存二字。上古神话赖之以全，汉代科技赖之以录，黄老遗说赖之以传。若失此书，女娲补天、后羿射日仅余断片残辞，汉初学术之真貌亦缺其一角。故《淮南子》虽成于淮南王门下，实为中国文化之公器，非一人一家之私言，班固列之杂家，良有以也。"
        ]
      }
