    interpretation: "《淮南子》之深层意义，在于它是汉初黄老政治思想的最后一次系统总结。武帝建元元年罢申商韩非之言，建元五年立五经博士，儒家渐成一尊；而建元二年刘安献书，恰在此转折关头，以道家统摄百家，与董仲舒《春秋繁露》之大一统路线分庭抗礼。元狩元年淮南国除，黄老之治退出政治舞台，《淮南子》遂成绝响。然其书不因政治之败而亡，反以文献之富传世：神话赖之以全，科技赖之以录，百家之说赖之以存。许慎、高诱为之作注，唐宋以下传习不辍。论西汉学术者，南有《淮南》，北有《春秋繁露》，一宗道，一尊儒，实为思想史之两极；而其兼收并蓄之气度，尤为后世子书所罕见。",
