    summary: "中平元年（184年）二月，太平道首领张角以「苍天已死，黄天当立，岁在甲子，天下大吉」为号，率三十六方徒众同时起事，部众皆头裹黄巾，史称黄巾军。起义旬日之间天下响应，众至百万，焚官府、杀长吏，京师震动。汉灵帝被迫解除党锢，许州郡自行募兵平叛，皇甫嵩、朱儁、卢植等分路征讨。同年冬，张角病卒，张梁、张宝先后战死，黄巾主力覆灭，余部转战多年。汉廷为速平叛乱而下放军权，州牧与地方豪强乘势拥兵自重，东汉大一统局面瓦解，群雄割据之端由此开启。",
    background: "东汉自汉桓帝、汉灵帝两朝，朝政由外戚与宦官交替把持，宦官侯览、曹节、王甫等先后擅权，士大夫因「党锢之祸」遭禁锢刑戮，贤才之路断绝。地方上豪强地主大肆兼并土地，失地农民沦为流民，或依附门客，或聚保山泽。自建宁元年（168年）至光和年间，中原疫病连年流行，百姓死亡枕藉，官府不恤。巨鹿人张角自称大贤良师，奉黄老道，创太平道，以符水咒说为人治病，病者多愈，百姓信之。十余年间，张角遣弟子八人分行四方，信徒发展至数十万，遍布青、徐、幽、冀、荆、扬、兖、豫八州。张角将信徒编为三十六方，大方万余人，小方六七千人，各立渠帅统辖，又以「苍天已死，黄天当立」为暗语，约定中平元年三月五日天下同起。张角还派大方渠帅马元义往来洛阳，联结中常侍封谞、徐奉等为内应，欲内外夹击，一举倾覆汉室。",
