          "至光和年间，张角已不满足于宗教影响，开始把信徒按照军事编制整编为三十六方。大方万余人，小方六七千人，各立渠帅统辖，实际上就是三十六支军队。张角又立暗语，令信徒在州郡官府门上用白土书写「甲子」字样，作为起事时内应的识别标记，并约定在中平元年（184年）三月五日，天下三十六方同日并起。",
