          "张角自称天公将军，其弟张宝称地公将军、张梁称人公将军，奉汉为「苍天」，自命为「黄天」，以五行相代之说论证汉祚已终、黄天当立。起义军所在之处，燔烧官府，劫略聚邑，州郡长官或死或逃，旬日之间，天下响应，京师震动。冀州、豫州、南阳、汝南各部黄巾众至百万，东汉立国近四百年，未有如此规模的民变。",
