    dynasty: "汉",
    era: "汉武帝元狩六年",
    year: {
      start: -117
    },
    summary: "霍去病（前140—前117），河东平阳人，大将军卫青外甥，汉武帝时名将，中国古代骑兵长途奔袭作战的代表人物。元朔六年（前123），十八岁为剡姚校尉，率八百骑深入大漠，功冠全军，封冠军侯。元狩二年（前121）两出河西，歼降匈奴数万众，河西走廊由此纳入汉朝版图。元狩四年（前119）漠北之战，封狼居胥山、禅于姑衍、登临翰海，拜大司马骠骑将军。元狩六年（前117）卒，年二十四岁，汉武帝发玄甲军送葬，起冢如祁连山。",
    background: "汉初匈奴强盛，屡屡南下。汉高祖刘邦于白登（今山西大同东北）被冒顿单于三十余万骑围困七日，脱险后被迫对匈奴和亲。此后七十余年，汉朝以宗室女、缯帛、粮食换取边境安宁，而匈奴仍岁岁入寇。经文景之治，汉朝国力充实，马政大兴。汉武帝即位后，决意改被动为主动。元光二年（前133），汉军设伏马邑，谋击军臣单于，事泄未成，汉匈彻底决裂。元朔二年（前127），卫青收复河南地，置朔方、五原郡；元朔五年、六年，卫青两出定襄，重创匈奴单于本部。霍去病为河东平阳人，其母卫少儿与县吏霍仲孺私通而生之。卫子夫得幸武帝、卫青以军功崛起之后，霍去病年十八为天子侍中，善骑射，由此步入军旅。",
    chapters: [
      {
        heading: "八百轻骑 冠绝全军",
        paragraphs: [
          "元朔六年（前123）春，大将军卫青率十余万骑兵出定襄击匈奴。霍去病时任剡姚校尉，年十八岁，随军出征。他亲率轻勇骑兵八百人，脱离汉军主力，直捣数百里之外的匈奴腹地。卫青本部此战斩获有限，而霍去病部斩捕首虏二千二十八级，超过其所部兵员两倍有余，史书称之为「过当」。",
          "这一役，霍去病部斩杀匈奴籍若侯产——单于祖父一辈的重臣，生擒单于叔父罗姑比，俘虏匈奴相国、当户等贵官多人。汉武帝大喜，以其功冠全军，封为冠军侯。「冠军」二字，自此成为霍去病的名号，也成为后世勇将的最高赞誉。一位少年将领，以一场奔袭战跻身汉军最高军功之列，而以骑兵长途奔袭破敌的新战法，也由此为朝野所重。"
        ]
      },
      {
        heading: "两出河西 廓清走廊",
        paragraphs: [
          "元狩二年（前121）春，汉武帝以霍去病为骠骑将军，率精骑一万出陇西。汉军转战六日，越过焉支山千余里，与匈奴短兵相接，杀折兰王，斩卢侯王，浑邪王部众溃散，休屠王祭天金人亦为汉军所获，匈奴右部为之震动。焉支山一战，使汉朝认识到匈奴右翼并非不可击破，为同年夏的第二次河西之战铺平了道路。",
          "同年夏，霍去病与合骑侯公孙敖分道出北地。公孙敖迷失道路，未能按期会合，霍去病毅然率孤军深入，越过居延泽，直抵祁连山下。此役俘虏匈奴裨小王以下七十余人，受降二千五百人，斩首俘虏三万二百级，浑邪王、休屠王所部精锐损失殆尽。匈奴民间流传悲歌：「失我祁连山，使我六畜不蕃息；失我焉支山，使我嫁妇无颜色。」",
          "连番惨败之后，伊稚斜单于欲召浑邪王、休屠王诛之。元狩二年秋，浑邪王决意降汉，武帝命霍去病率军渡河往迎。降营中多有动摇欲遁者，霍去病驰入其阵，斩杀企图逃亡者八千人，以铁腕安定其众，护送浑邪王四万余众东归长安。汉廷随即在浑邪王、休屠王故地设置武威、酒泉二郡，其后又增置张掖、敦煌，史称河西四郡。河西走廊正式纳入汉朝版图。"
        ]
      },
      {
        heading: "封狼居胥 勒石翰海",
        paragraphs: [
          "元狩四年（前119）春，汉武帝倾全国之力，征集战马十四万匹、步卒数十万，命大将军卫青与骠骑将军霍去病各率五万精骑，分道出定襄、代郡，意图跨越大漠，一举歼灭匈奴主力。武帝将战斗力最强的部队尽数配属霍去病，使其担任主攻。霍去病部出代郡后长驱直入，深入二千余里，渡过大漠，直逼匈奴左贤王王庭。",
          "两军接战，霍去病部大破左贤王主力，歼敌七万四百四十三级，俘虏屯头王、韩王等三人，将军、相国、当户、都尉八十三人，左贤王仅以身免。霍去病乘胜追击，直至狼居胥山，举行祭天封礼；又至姑衍行禅礼，祭告天地；随后登临翰海。班师途中取食于敌，军行极远而粮草不绝，堪称古代骑兵长途奔袭作战的典范。",
          "还朝之后，汉武帝拜霍去病为大司马骠骑将军，秩禄与位望比于大将军卫青，汉军最高统帅遂由卫霍二人并掌。经此一战，匈奴主力损失惨重，远走西北，漠南再无匈奴王庭，汉朝北部边患暂得平息。自高祖白登之围以来，汉朝对匈奴七十余年的被动和亲与防御，至此根本扭转，汉匈之间的攻守之势全面易位。"
        ]
      },
      {
        heading: "将星早陨 冢象祁连",
        paragraphs: [
          "元狩六年（前117）九月，霍去病遽然病逝，年仅二十四岁。汉武帝深为悲恸，调发属国玄甲军士列阵送葬，队伍自长安城一直绵延至茂陵，前后百里不绝；又下令将其坟墓筑成祁连山的形状，以铭记他廓清河西的功业，并定其谥号为「景桓」，取「并武与广地」之意。",
          "霍去病之死因，正史不载。《史记》《汉书》仅记「元狩六年卒」，并无片言及于死因。后世史学界多有推测，或以为其连年征战、积劳成疾，或以为塞外染疫、不治而亡，皆无确证，主流观点倾向于因病早逝。以其二十四岁之龄、骠骑将军之尊，葬礼规格之高，为汉初功臣所罕匹。",
          "霍去病用兵不拘古法。汉武帝曾欲教以孙吴兵法，他答曰：「顾方略何如耳，不至学古兵法。」武帝又为之修建宅第，命他前往观看，他答曰：「匈奴未灭，无以家为也。」两句言语，千载之后犹有回响，成为后世武将精神的写照。其四出塞外、每战必克的短促一生，恰与汉武帝时代昂扬进取的国势彼此映照。"
        ]
      }
    ],
    interpretation: "霍去病的崛起，根本在于汉武帝朝对匈奴战略的根本转变。自白登之围后七十余年，汉朝以和亲、互市羁縻匈奴。元光二年（前133）马邑之谋后，汉匈决裂，武帝决意以攻代守。凭借文景之治积累的国力，汉朝组建起大规模骑兵军团，以机动对机动、以奔袭对奔袭，霍去病正是这一战法最彻底的执行者。他取食于敌、轻装深入，将骑兵的机动性发挥到极致。河西之战使汉朝控制河西走廊，隔绝羌胡，为张骞凿空之后经营西域奠定地缘基础；漠北之战则使匈奴远遁，汉朝北境得安数十年。其人早逝，使汉武帝失去最善长途奔袭的统帅，此后汉匈战争转入长期相持，汉朝国力渐耗。",
