    summary: "郡国并行制是西汉初年实行的郡县制与分封制并行的国家行政制度。汉高祖刘邦惩秦孤立之亡，在直属中央的郡县之外，分封异姓功臣与同姓子弟为王，形成郡县与封国犬牙交错的格局。异姓王翦除殆尽后，白马之盟确立「非刘氏而王者，天下共击之」之制，同姓九王分镇东方。文景之世诸侯坐大，七国之乱后，诸侯王唯得衣食租税，不与政事。汉武帝行推恩令，藩国分剖殆尽，郡国并行终归于实质上的郡县制。此制是从分封余绪走向中央集权的过渡环节。",
    background: "秦并天下，废分封而行郡县，然而二世而亡。汉高祖刘邦出身亭长，乘秦末大乱而定天下，其取天下实赖诸侯之力。楚汉相争时，刘邦为换取韩信、彭越、英布等竭力效死，不得不裂土封王；及至汉五年（前202年）即帝位，异姓七王已跨州连郡，据有东方故六国之地。汉初君臣检讨秦亡教训，多以为秦始皇子弟无功无封，海内孤立，致陈胜一呼而天下瓦解，无宗室藩屏之救。刘邦既欲巩固刘氏政权，又须酬答功臣，于是在秦郡县之上复立封国，郡县直属中央，封国分授王侯。汉六年（前201年）起，刘邦一面翦除异姓王，一面分封同姓九王，郡国并行之制由此确立。",
