    interpretation: "郡国并行制是汉初在特殊形势下作出的制度折中。秦废分封而速亡，使汉初君臣认定宗室屏藩不可少；而异姓功臣拥兵据地，又不能不封。中央直辖关中、巴蜀，以郡县控制根本之地；分封同姓于东方，以宗法血缘镇抚新附之土。这在汉初国力未充之时，确有稳固政权之功。然而分封与中央集权在逻辑上终不相容：诸侯势大必生异心，血缘疏远必成仇雠。从贾谊众建到主父偃推恩，汉廷以制度性消解取代武力翦除，兵不血刃而尽收诸侯之权。郡国并行的终结，标志着中央集权体制的成熟，为汉武帝时代的大一统奠定制度基础，也证明单靠宗法血缘已无法约束政治权力。",
