          "元狩二年（前121），汉军大举击匈奴，李广数自请行，以郎中令将四千骑出右北平，博望侯张骞将万骑与之异道。行数百里，遭左贤王四万骑围困，汉军大恐。李广命其子李敢率数十骑直贯敌阵，自左出右而还，以安军心；随即布圆阵外向，持满不发，待敌逼近齐射，鏖战一日，汉兵死者过半，矢且尽。次日再战，适张骞军至，匈奴解围去。此役李广以四千当四万，力战不失，依汉法「军功自如」，无赏无罚；张骞留迟后期，赎为庶人。李广曾与望气者王朔燕语，自叹部下才能不及中人者数十人以军功取侯，而广终无尺寸之功，岂吾相不当侯耶？王朔以广昔在陇西诈杀降羌八百人对之，李广终身耿耿。"
