          "武帝晚年多猜忌，征和二年（前91），丞相公孙贺父子下狱死，诸邑、阳石公主及长平侯卫伉皆坐诛。江充以治巫蛊督责京师贵戚，与太子刘据有隙，遂使人于太子宫掘地得桐木人。太子不能自明，七月矫节发兵，斩江充，与丞相刘屈氂大战长安，血染沟渠，死者数万。太子兵败，南奔湖县，吏围捕，自缢，史良娣、皇孙并遇害，卫皇后以玺绶自杀。汉家储君与卫氏外戚，一朝覆灭。",
          "征和三年（前90），贰师将军李广利出击匈奴，兵败降敌，七万众尽没。四年，搜粟都尉桑弘羊等奏请增戍轮台、募民屯田。武帝下轮台之诏，痛陈「朕之不明」，申明「当今务在禁苛暴，止擅赋，力本农，修马复令」，拒却远戍，拜田千秋为富民侯，以明休息之意，国策为之一转。后元二年（前87）二月，武帝崩于盩厔五柞宫，年七十，葬茂陵，谥孝武，庙号世宗。遗诏霍光、金日磾、上官桀、桑弘羊辅佐幼子昭帝刘弗陵。班固赞曰「雄才大略」，亦惜其不能守文景之恭俭以济斯民。"
