    interpretation: "刘协之悲剧，实为制度崩解之悲剧。东汉幼主继位、外戚秉权、宦官夺权，三者循环百余年，至桓、灵之世，朝廷信用与统治根基已两竭。黄巾起后，州牧掌兵，中央所余唯皇帝名分与正统旗号。董卓废立，以边将秉朝政，开兵强马壮者当为天子之局；曹操迎帝都许，以汉室余威收拾人心、征伐四方，降低统一成本，此即挟天子以令诸侯之实质。帝之价值尽在正统符号，故董承一败即束手；待曹操平定河北、封公封王，符号即可弃去。禅让以三代揖让为表，行强臣篡代之实，曹丕开此例，司马氏继之，魏晋以下百余年政权更迭多循此轨。帝个人无能为力，因汉室既无可恃之兵，亦无可信之臣，非一君之过。",
