          "更始元年（23年）十月，更始帝遣刘秀以破虏大将军行大司马事持节北渡黄河，镇慰河北诸郡。他沿路考察官吏，平理冤狱，释放囚徒，废除王莽苛政，恢复汉家制度，所过州县争相迎附。其时河北群雄并起：邯郸有卜者王郎，诈称成帝之子，自立为帝，割据一方；又有铜马、大彤、青犊等部数十万流动作战。刘秀初至河北，势单力薄，一度为王郎追兵所逼，情势危殆。",
          "危急之际，上谷太守耿况、渔阳太守彭宠各遣突骑来援，信都、和戎二郡亦归从，刘秀遂得立足。更始二年（24年）五月，汉军攻破邯郸，斩王郎。随后刘秀收编铜马诸部，众至数十万，威声远播，关西号之「铜马帝」。他在河北广揽人才，邓禹追献定天下之策，冯异、岑彭、耿弇、吴汉等名将云集麾下，河北遂成帝王之基。更始帝封为萧王，令其罢兵归长安，刘秀拒不从命，实质已与更始分道扬镳。",
