          "统一之后，刘秀汲取前汉异姓王之乱与王莽篡汉的教训，以柔道治国。建武十三年（37年），大封功臣三百六十五人为列侯，食邑丰厚，却尽释其兵权；功臣不预朝政，亦不得任职州郡，得以安享尊荣。同时擢用文法吏，以经术与吏能取士。《后汉书》称其「退功臣而进文吏，戢弓矢而散马牛」。他更削弱三公，事归尚书台，以天子近臣掌控机要，皇权因之空前强化。",
          "建武十五年（39年），刘秀下诏度田，令各州郡核实垦田数目与户口年纪，以求赋役均平。其时豪强地主隐匿田土、荫附人口成风，度田诏下，郡县大姓群起抗拒，长吏多有被杀者。刘秀一面严令推行，诛杀带头叛乱者，一面宽待自首之人，恩威并施，度田终得推行全国。东汉初年垦田与户口由此大增，国家赋役基础重获稳固。同年裁并四百余县，吏职减去十之四五，朝廷开支与百姓负担一并减轻。",
          "与民休息亦是中兴要义。刘秀在位期间，前后九次下诏释放奴婢或提高其法律地位，严禁虐杀奴婢；建武六年（30年）恢复田租三十税一；又大兴水利，修治黄河与汴渠，移民实边。他生活简朴，不好珍玩，每日视朝，日仄方罢，数引公卿郎将讲论经义，夜分乃寐。天下得享太平，户口由凋敝渐次滋殖。中元二年（57年）二月，刘秀崩于洛阳南宫，年六十二，葬于原陵，谥曰光武，庙号世祖。"
