    interpretation: "刘秀是古代帝王中少有的兼具马上功业与治世之才者。其成功一半在于时势，一半在于性格：昆阳之战见其勇，兄长见害见其忍，经略河北见其谋。天下既定，他不效汉高祖之诛戮功臣，而以柔道求两全：厚其爵禄而夺其权柄，既全君臣之义，又免骄兵悍将尾大不掉之患。尚书台之强化与度田之推行，则是皇权下移地方的实际尝试。度田虽成，却不得不与豪强有所妥协，田庄经济继续膨胀，为东汉末年的门阀士族与地方割据埋下远因。他重建的汉室延续近二百年，其以柔道御天下的政治智慧，成为后世开国之君与守成之主反复取法的典范。",
