          "其后匈奴五单于争立， 日逐王先贤掸于神爵二年（前60年）率众降汉，匈奴僮仆都尉由此罢撤，西域尽免于匈奴役属。汉乃拜郑吉为西域都护，治乌垒城（今新疆轮台东南），督察乌孙、康居等三十六国，汉家号令颁行西域，都护府之设使中原王朝对西域的管辖由使节往来进为常设政令。甘露三年（前51年）春正月，呼韩邪单于稽侯狦亲至长安朝见，位在诸侯王之上；自是匈奴称臣保塞，北边晏然者数十年，武帝未竟之业至宣帝而成。"
