    interpretation: "汉宣帝的治术，深深烙着他早年的民间印记。班固称孝宣之治信赏必罚、综核名实，司马光亦于《资治通鉴》中称其明于治体。他困于襁褓、长于闾巷，深知百姓苦乐系于官吏良窳，故亲政后以吏治为立国之本：久任以责成效，考课以定赏罚，循吏如黄霸、龚遂辈出，户口岁增，刑狱屡平。对外则趁匈奴内乱，设西域都护府统辖三十六国，使西域正式归于中原王朝政令之下，为后世疆域治理开一先例。其遗产有二：制度层面，昭宣中兴修复武帝晚年虚耗之国力，西汉再得数十年安定；教训层面，他已洞察太子纯任德教之弊，却终未改易储君，此后元、成以降，外戚与儒生迭秉朝权，西汉之衰，实肇于此。",
