          "然而局面陡转。永平十八年（75年），明帝驾崩，北匈奴趁机反扑，焉耆、龟兹攻杀都护陈睦，耿恭被围于疏勒城。耿恭率数百人坚守数月，粮尽食铠弩筋革，凿山为井，誓死不降；建初元年（76年），汉军范羌率两千人冒雪驰援，迎耿恭东归，入玉门关时仅余十三人，「十三将士归玉门」由此千古流传。西域都护一度罢废，但班超留驻疏勒，以三十六人纵横捭阖，章帝、和帝两朝终于重定西域，永元三年（91年）班超任西域都护。明帝时代的经略，为此后班超三十一年西域功业奠基，也确立了中原王朝经营西域的基本范式。"
