    summary: "汉高祖刘邦（前256年—前195年，生年一说前247年），字季，沛县丰邑人，西汉开国皇帝。秦末起兵于沛，率先入关，约法三章，深得民心；鸿门宴后受封汉王，经五年楚汉战争击败项羽，前202年称帝，定都长安，建立汉朝。在位期间行郡国并行之制，轻徭薄赋，与民休息；又翦除异姓王，斩白马立盟「非刘氏而王，天下共击之」，奠定汉室四百年基业。",
    background: "秦始皇统一六国后，厉行苛法，徭役连年。二世胡亥即位，赵高弄权，赋敛愈急，民不聊生。前209年七月，陈胜、吴广在大泽乡揭竿而起，天下云集响应，六国旧贵与各地豪杰并起反秦。刘邦本是沛县丰邑农户之子，曾任泗水亭长，负责捕捉盗贼、押送役徒。一次他押送徒役赴骊山，途中逃者过半，按秦律失期当斩，索性尽释众人，携十余人亡匿芒砀山泽。陈胜起义后，沛县父老杀县令，迎刘邦回城，立为「沛公」，聚众三千人，旗帜尚赤，汇入反秦洪流。与此同时，项梁、项羽叔侄起兵于吴，拥立楚怀王之孙熊心，各路义军与秦军展开拉锯，天下陷入群雄逐鹿之局。",
