          "周亚夫深沟高垒，另遣轻兵断绝淮河、泗水间粮道，吴军久战乏食，进退失据。吴王濞欲求决战，挑战数次，周亚夫按兵如故。及至吴军粮尽，士卒饥散，夜遁者过半，周亚夫乃挥军追击，一战破之。吴王濞弃军南奔，渡长江走东越，东越王受人指使，以劳军为名刺杀濞，传首长安。楚王刘戊败走，自杀于军中。胶西、胶东、菑川、济南四王兵败，或自杀或伏诛；赵王遂坚守邯郸，至十月城破自杀。自正月起兵至叛平，前后不过数月，七国之地尽归汉廷。"
