          "七国之乱的平定，是汉初制度的一大转折。高祖分封同姓，本欲以骨肉藩屏汉室，不及七十年，宗室至亲反成腹心之患。贾谊、晁错之削藩，实为时势所迫。经此一役，中央与地方的力量对比彻底逆转，大一统的政治格局渐次稳固。及至汉武帝，行推恩之令，分封之弊根除，汉室遂能集举国之力于外攘匈奴、内兴功业。后人论汉室强盛，往往追述于此。"
