    interpretation: "七国之乱表面上是一场宗室叛乱，实质上是汉初分封制与郡县制之争的总爆发。高祖大封同姓，本意以血缘藩屏皇权，但数十年后血缘渐疏，诸侯据地自专，遂成尾大不掉之局。吴王濞以一己之私怨纠合六国，以「清君侧」为名，行夺鼎之实，其败亡不在兵不强、粮不足，而在名不正、心不齐——七国各怀算计，乌合之众耳。景帝诛晁错，是乱世君主的权宜，也是刻薄寡恩的污点；然其能改过任将，终收全功。此后诸侯唯衣食租税，中央集权大固，为汉武盛世铺平了道路。",
