    summary: "西汉武帝时司马迁撰，约成于征和二年（公元前91年）。全书一百三十篇、五十二万六千五百字，上起黄帝、下迄汉武帝太初年间，记述约三千年史事，首创本纪、表、书、世家、列传五体结合的纪传体，是中国第一部纪传体通史，亦为二十四史之首。司马迁以「究天人之际，通古今之变，成一家之言」为宗旨，融史料、文学与思想于一炉，奠定中国古代正史的格局与精神。",
    background: "汉承秦祚，至武帝时已历七十余年，海内一统，府库充实。武帝罢黜百家、独尊儒术，又北击匈奴、通使西域，王朝急需对自古以来的制度沿革与天人秩序作一系统总结。司马迁之父司马谈任太史令，学天官于唐都，受《易》于杨何，习道论于黄子，志在续《春秋》而未就；元封元年（公元前110年）临终执司马迁之手，遗命论著。司马迁二十岁南游江淮，北涉汶泗，后奉使巴蜀、昆明，足迹半天下。元封三年（公元前108年）继任太史令，得尽读石室金匮之书。太初元年（公元前104年）参与制定《太初历》，同时动笔著书。天汉三年（公元前98年）因李陵之祸受宫刑，隐忍发愤，前后历十四年乃成。",
    chapters: [
      {
        heading: "五体肇始，三千年史",
        paragraphs: [
          "《史记》全书一百三十篇，由五体构成：本纪十二篇，编年记述帝王理政得失，为全书纲领；表十篇，以年表、月表列历代沿革，省却繁文；书八篇，分述礼、乐、律、历、天官、封禅、河渠、平准，专记典章制度与社会经济；世家三十篇，叙诸侯封国及孔子、陈涉等足以左右历史进程之人；列传七十篇，网罗将相、游侠、刺客、商贾、四夷各色人物。上起黄帝，下迄太初（公元前104年），前后约三千年，合五十二万六千五百字。",
          "此前的史书，《春秋》为编年，《国语》《战国策》为国别，皆以事为纲。《史记》首创以人物为纲的纪传体，本纪立其骨架，世家、列传充其血肉，书与表经纬其间，帝王将相与刺客游侠同入史册。司马迁破例立《孔子世家》以尊圣人，列《陈涉世家》以彰首义，项羽未尝称帝而入本纪，吕后临朝称制亦入本纪，皆以实际历史地位为准，不以名位拘限。这一体例为班固《汉书》所承，稍变通史为断代，其后正史递相祖述，二十四史遂皆以纪传为正体。"
        ]
      },
      {
        heading: "李陵之祸，发愤著书",
        paragraphs: [
          "天汉二年（公元前99年），武帝命贰师将军李广利出击匈奴，骑都尉李陵自请率步卒五千出居延，深入浚稽山，遭单于八万骑兵围困。李陵军转斗千里，杀伤过当，矢尽道穷，救兵不至，力屈而降。武帝震怒，群臣随声诋毁李陵；独太史令司马迁为之辩护，谓李陵事亲孝，与士信，常奋不顾身以殉国家之急，观其本意，或欲寻机报汉。武帝以其言意在诋毁李广利，遂下迁于狱。天汉三年（公元前98年），司马迁受宫刑。",
          "宫刑为奇耻大辱，司马迁本欲自绝，然念及司马谈元封元年临终遗命「无忘吾所欲论著矣」，又以周文王拘羑里而演《周易》、孔子厄陈蔡而作《春秋》、屈原放逐而赋《离骚》、左丘失明而厥有《国语》自况，遂隐忍苟活，出狱后迁中书令，专意著书。他在《报任少卿书》中写下「人固有一死，死有重于泰山，或轻于鸿毛」，自陈所以隐忍偷生，唯恨文采不表于后世。自太初元年动笔，至征和二年（公元前91年）前后告成，凡十四年。"
        ]
      },
      {
        heading: "藏之名山，传之其人",
        paragraphs: [
          "书成之后，司马迁写定正、副两本，「藏之名山，副在京师」，生前未敢公然行世。汉宣帝时，其外孙平通侯杨恽读而善之，遂宣扬于外，《史记》始渐行于世。汉元帝、成帝之际，博士褚少孙补《武帝本纪》《三代世表》《建元以来侯者年表》《龟策列传》《日者列传》等缺佚篇章，今本中「褚先生曰」即其补笔。东汉班彪作《史记后传》数十篇，其子班固因之撰《汉书》百篇，沿纪传之体而断代为史。",
          "《史记》传世，注家代兴。南朝宋裴骃撰《史记集解》，唐代司马贞撰《史记索隐》，唐张守节撰《史记正义》，合称「三家注」，与正文并行千载。刻本以南宋黄善夫本、明南北监本、清同治金陵书局本为著。今本一百三十篇中，《孝武本纪》系后人取《封禅书》剪裁凑成，非司马迁原文；而《项羽本纪》《李将军列传》《刺客列传》诸篇之精善，二千年来诵之不衰。"
        ]
      },
      {
        heading: "史家绝唱，无韵离骚",
        paragraphs: [
          "司马迁写人，不避成败，不掩善恶。项羽兵败垓下、自刎乌江，而《项羽本纪》写得悲壮淋漓；李广终身不得封侯，而《李将军列传》使「桃李不言，下自成蹊」传诵千古；荆轲刺秦，易水悲歌，须眉如见；韩信少时受辱胯下、登坛拜将，前后映照，栩栩如生。其文善序事理，辩而不华，质而不俚，为后世传记文学之宗；唐宋古文家韩愈、柳宗元、欧阳修无不取法，明清小说戏曲取材于《史记》者尤不可胜数。",
          "史学上，司马迁立「不虚美，不隐恶」之实录准则，班固许为「其文直，其事核，故谓之实录」。他以「通古今之变」的眼光考察制度兴革、人事成败：八书以纪制度，《货殖列传》以述经济，承认求利乃人之常情，《平准书》直书汉武财政之困，皆卓识远见。其纪传通史与司马光《资治通鉴》编年通史并峙，二书并称「史学双璧」，二氏并称「两司马」，《史记》居二十四史之首，影响二千余年。"
        ]
      }
    ],
    interpretation: "《史记》之伟大，不在纪事之详，而在其史识与胆魄。司马迁把帝王将相与游侠刺客、日者龟策同列一编，承认各色人物皆足以左右历史进程，已具平视千古的胸怀。他写成败而不以成败论人：项羽入本纪，陈涉入世家，李广之憾、李陵之冤皆秉笔直书，故班固称其「不虚美，不隐恶」。八书志制度，《货殖》论生计，《平准》记财政，可见其目光不在宫廷一隅，而在国计民生与制度沿革。纪传一体自《史记》创立，班固以下二十三部断代史皆承之，遂为正史唯一正体。文学上开传记之宗，思想上叩问天道，「傥所谓天道，是邪非邪」，其怀疑与追问至今仍有力量。",
