    dynasty: "汉",
    era: "建光元年",
    year: {
      start: 121
    },
    summary: "东汉建光元年（121年），汝南召陵人许慎历时二十余年，编成《说文解字》十五卷。全书收字九千三百余个、重文一千一百六十余个，以小篆为主，兼收古文、籀文，首创五百四十部首统摄全部字形，并按象形、指事、会意、形声、转注、假借「六书」逐一剖析结构、考究本义。这是中国第一部系统分析字形、探究字源的字典，奠定了文字学的根基，书成后由其子许冲献于朝廷，历代传习不衰，至清代发展为专门之学。",
    background: "汉武帝独尊儒术之后，经学立于学官，但经义的解释众说纷纭。立于学官的今文经学家，仅凭汉代通行的隶书字形臆解文字，甚至附会谶纬，穿凿之说层出；而新出的古文经本，如孔子壁中书、张苍所献《春秋左氏传》，所用籀篆古文反被斥为「好奇立异」。当时虽有《凡将》《急就》等字书，却只是蒙学识字之编，并不考究字理。文字解释的混乱，直接动摇经义的权威。许慎师从古文经学大师贾逵，精通《五经》，时人誉为「五经无双许叔重」。他深感「人用己私，是非无正」，要厘清经义，必先弄清文字本义。汉和帝永元十二年（100年），他着手编撰《说文解字》，此后二十余年遍考群书、逐字辨析。这既是正本清源的学术志业，也是对当时文字乱象的一次系统清理。",
    chapters: [
      {
        heading: "博学治字，廿载成编",
        paragraphs: [
          "许慎字叔重，汝南召陵（今河南漯河召陵）人，约生于汉明帝、章帝之际。史称他「性淳笃，少博学经籍」，连一代名儒马融也对他推敬有加，时人因有「五经无双许叔重」之誉。他先被举为孝廉，历任汝南郡功曹、太尉南阁祭酒，又出任洨长（洨县在今安徽固镇一带）。为官之外，他潜心经术，因痛感当时经师解说经义多凭臆断，先著《五经异义》以辨析诸说分歧；而经义之争的症结往往在文字本身，于是发愿再著一书，逐一弄清每个字的本形、本音与本义。",
          "汉和帝永元十二年（100年），许慎正式动笔编撰此书。他从《诗》《书》《礼》《易》《春秋》及诸子百家、汉代律令、郡国奏章中广搜字形，共得九千三百余字，又收集古文、籀文等异体写法（书中称为「重文」）一千一百六十余个。每字先列小篆，次列重文，再释义、注音，并引经传文献、方言俗语为佐证，务求穷源究委。安帝建光元年（121年），全书十五卷终于编成，许慎已年逾六旬。其子许冲于当年九月上表诣阙献书，安帝下诏赐布四十匹，《说文解字》自此传世。"
        ]
      },
      {
        heading: "五百四十部，统摄万殊",
        paragraphs: [
          "《说文解字》最了不起的创举，是确立了部首系统。许慎把九千三百多个汉字按偏旁归为五百四十部，每部以一个统领字形为部首，部首本身也按形体意义相连的次序排列，从「一」部开始，到「亥」部结束，暗含「始一终亥」、万事万物皆有所归的深意，即他自己所谓「据形系联」「引而申之，以究万原」。这一编排使查字、辨字第一次有了系统可循。后世《康熙字典》归纳为二百一十四部，今天各种字典的部首检字法，源头都在这里。",
          "释义的方法，许慎系统运用「六书」：象形、指事、会意、形声、转注、假借。他在叙中举例说明：象形是「画成其物，随体诘诎」，如日、月；指事是「视而可识，察而见意」，如上、下；会意是「比类合谊，以见指撝」，如武、信；形声是「以事为名，取譬相成」，如江、河。他特别指出形声字占最大比例，揭示了汉字由形符与声符组合而成的核心结构规律。这是中国历史上第一次对汉字造字方法作出完整的理论概括，此后两千年谈汉字构造，基本沿用这一框架。",
          "书中还保存了丰富的古文字资料：古文（战国时东方六国通行的文字）、籀文（相传出于周宣王太史籀所编《史籀篇》的大篆），以及各地的或体、俗体。许多先秦的字形字义赖此书得以保存。比如「册」字象竹简编连之形，「典」字象双手捧册，后人据此才理解先秦典籍制度。若无《说文》承上启下，商周甲骨金文与后世楷书之间，便少了一座可以依托的桥梁。"
        ]
      },
      {
        heading: "历代传注，蔚为显学",
        paragraphs: [
          "《说文解字》在魏晋南北朝传习不绝，但辗转传抄，字形渐失本真，唐代李阳冰等曾加以刊定，也多有窜改。五代乱离之后，版本尤为杂乱。宋太宗雍熙三年（986年），诏命徐铉与句中正、葛湍等共同校定《说文解字》，世称「大徐本」，今天通行的本子即以此为祖。徐铉在校定中补入四百余个后起字（「新附字」），并为每字添加反切注音，虽有增益，也有失许慎原貌之处。其弟徐锴另著《说文解字系传》，世称「小徐本」，两书并行，宋代《说文》之学遂有根基。",
          "清代乾嘉考据学大兴，《说文》研究达到顶峰，形成专门之学，成就最著者为「说文四大家」：段玉裁《说文解字注》、桂馥《说文解字义证》、王筠《说文句读》与《说文释例》、朱骏声《说文通训定声》。段玉裁积数十年之力，稿经数易，至嘉庆二十年（1815年）才刻成其书，被公认为治《说文》的集大成之作。一部书滋养一专门之学，绵延千数百年，在中国典籍史上并不多见。",
          "近代以来甲骨文、金文、简牍大量出土，学者用地下实物印证《说文》，证明许慎的许多说解确有古据，也辨明了其中若干附会，如「一贯三为王」「推十合一为士」之类，实为汉代人据小篆字形所作的推演。但无论校正还是补正，都以《说文》为出发点。今天的汉字规范、古文字考释、字典编纂，仍以此书为基本参照。它作为汉字体系第一座系统化坐标的地位，历经两千年未曾动摇。"
        ]
      }
    ],
    interpretation: "《说文解字》的意义远不止一部字典。它是许慎面对经学纷争给出的答案：要弄清经典本义，先要弄清文字本义；而文字本义，只能从字形结构中去求。这一思路把文字从经学附庸提升为独立考察的对象，文字学由此成为专门之学。五百四十部首把看似散漫的汉字组织为以形系联的体系，后世一切字典的部首编排都绕不开它。书中保存的小篆、古文、籀文，是连接甲骨金文与后世楷书的关键环节；所录汉代方言、俗语、名物制度，更是两汉语言文化的活化石。中国人两千年间对自身文字的系统认识，正是从许慎这九千余字的条分缕析开始的。",
