          "单于幽苏武于大窖中，绝不饮食。天雨雪，苏武卧啮雪，和毡毛并咽之，数日不死，匈奴以为神。乃徙之北海上无人处，使牧羝，声言「羝乳乃得归」。廪食不至，则掘野鼠、取草实而食之。杖汉节牧羊，卧起操持，节旄尽落。十九年间，凛然一节，未尝少屈。",
          "李陵与苏武同为侍中，素相善。其兵败降匈奴后，奉单于命至海上，置酒设乐，劝曰：「人生如朝露，何久自苦如此！」苏武答以父子之恩、臣子之义，虽蒙斧钺汤镬，诚甘乐之；臣事君犹子事父，子为父死无所恨。李陵复欲再言，苏武曰：「王必欲降武，请毕今日之驩，效死于前！」李陵见其至诚，叹曰「义士」，自愧罪通于天，泣下沾衿，与武决去。"
