          "元朔二年（前127年），主父偃上书陈诸侯之害：『古者诸侯不过百里，强弱之形易制；今诸侯或连城数十，地方千里，缓则骄奢易为淫乱，急则阻其强而合从以逆京师。』因进策曰：『愿陛下令诸侯得推恩分子弟，以地侯之。彼人人喜得所愿，上以施德，实分其国，不削而稍自弱矣。』武帝深然其言。春正月，乃下诏曰：『梁王、城阳王亲慈同生，愿以邑分弟，其许之。诸侯王请与子弟邑者，朕将亲览，使有列位。』",
