    interpretation: "理解王昭君，须分清人物、制度和后世故事三个层次。《汉书》《后汉书》没有画工毛延寿，她的自请远嫁却有明确记载。汉武帝以后的长期战争已重创匈奴，宣帝时内乱又削弱其力量，呼韩邪称臣使汉朝从被动求和转为秩序主导，赐婚正是这一权力变化的仪式化表达。收继婚冲突时，汉成帝令她「从胡俗」，说明维持联盟优先于个人处境。数十年安宁并非仅靠一名女子，而是册封、礼赐、互市、边防与单于政治选择共同支撑的结果。《汉书》称当时「三世亡犬吠之警，黎庶亡干戈之役」，虽近颂词，仍可见和亲体系的实效。后世诗文戏曲不断改写她，因个人命运最便于承载家国感慨；若只见悲剧美人，便遮蔽了她在汉匈关系中的实际作用。",
