          "文帝十三年（前167年），太仓令淳于意坐法当刑，其少女缇萦上书，愿没入官婢以赎父罪。文帝怜其意，下诏自责「朕德薄而教不明」，并宣布废除肉刑：以髺钳城旦舂代黥刑，以笞三百代劓刑，以笞五百代斩左趾。这是中国法制史上第一次以法令形式废止残人肢体的肉刑。惟其中斩右趾改入死刑，时人已有「外有轻刑之名，内实杀人」之讥。",
