    interpretation: "文景之治的根基，在于对秦亡教训的深刻反省。秦以法家严刑、徭役无度而二世骤亡，汉初君臣遂以黄老清静无为相尚，轻徭、薄赋、省刑，看似消极退守，实则以「藏富于民」积蓄国力。田租三十税一、二十始傅、废除肉刑，桩桩都把民力从国家机器的重压下释放出来，于是户口繁息、粟腐贯朽，府库之充盈终为汉武帝北击匈奴、开疆拓土提供了物质资本。窦太后在景帝朝仍持黄老之治，直到武帝建元年间才改弦更张。后世论盛世，必以文景为标尺，唐贞观、明仁宣诸政，无不奉为典范。然其治亦有局限：对匈奴一味和亲隐忍，边患未除；诸侯坐大终须以战争解决；宽简之政下土地兼并渐起，流民问题在武帝初年已经显现。",
