          "武帝闻变，怒甚，命丞相刘屈氂发兵捕斩反者。太子兵与丞相军合战于长安街巷，两军相攻五日，死者数万人，血流入沟渠，京师震恐。太子兵寡，遂败，与二子出长安东奔，至湖县（今河南灵宝一带）匿于泉鸠里。武帝遣使者收卫皇后玺绂，卫子夫自杀，卫氏宗族株连者甚众。八月，县吏发卒围捕泉鸠里，太子闭户自刎，二子同日遇害。其孙刘病已尚在襁褓，亦被系郡邸狱，赖廷尉监丙吉周全，得免于死。是狱自皇后、太子、公主、丞相以下，牵连伏诛者数万人，公卿夷灭者数十家，西汉立国百余年未有之惨祸也。"
