          "征和三年（公元前90年），丞相刘屈氂坐与贰师将军李广利诅咒武帝、谋立昌邑王，事觉被腰斩，李广利兵败降匈奴，觊觎储君之李氏外戚集团亦随覆灭，朝局再经大洗牌。征和四年（公元前89年），桑弘羊等奏请屯田轮台，武帝下诏驳回，痛陈既往穷兵黩武之失，罢兵屯田，禁苛暴，止擅赋，与民休息，是为著名之轮台诏。后元二年（公元前87年）武帝崩，昭帝立，霍光辅政。后戾太子之孙刘病已入继大统，是为汉宣帝，追谥刘据曰「戾」，葬于湖县，巫蛊之祸余波始尽。"
