          "楚汉相持数年，刘邦多次在荥阳一线被项羽击败，士卒死伤惨重，甚至几次仅以身免。每逢危机，萧何总能及时从关中征调新兵、转运军粮，使刘邦重整旗鼓。《史记·萧相国世家》记载：「关中事计户口转漕给军，汉王数失军遁去，何常兴关中卒，辄补缺。」这是萧何最实在的功绩。",
          "高祖五年（前202年），项羽败死垓下，天下初定。论功行赏时，群臣以曹参攻城野战功多为第一。刘邦力排众议，定萧何为第一，封酂侯，并赐带剑履上殿、入朝不趋的特殊待遇。刘邦的理由是：诸将如猎犬，逐兔有功；萧何如猎人，发现猎物指示路径，是「发踪指示」之功。萧何的功劳，在于战略后勤与制度建设，而非战场厮杀。"
