    interpretation: "萧何的历史地位，不在于战场上的赫赫战功，而在于他对国家制度建设的深远贡献。咸阳收书一事，看似不起眼，实则体现了极高的战略眼光：在乱世之中，武力可以攻城略地，但要建立长治久安的政权，必须掌握整套行政运作体系——户籍、律令、舆图、档案。萧何是刘邦集团中唯一意识到这一点的人。《九章律》的制定，奠定了两汉法制基础。萧何与韩信、张良并称汉初三杰，刘邦的评价「镇国家，抚百姓，给馈饷，不绝粮道，吾不如萧何」，是对其功绩的最好概括。萧何死后，曹参沿用其法，开创清静无为的治国局面，为文景之治奠定了制度基础。可以说，汉朝四百年基业，萧何是奠基者之一。",
