    interpretation: "张衡之学，根柢在太史之职。东汉以谶纬治国，天人感应之说笼罩朝野，而太史令须以实测星象、推步历法为务，张衡遂以观测证验之精神，与图谶虚妄之说相抗，尝上疏请禁图谶。其浑天仪、地动仪皆因职守而作，非文人清玩；然其器虽精，后世莫能继——地动仪失传于汉末乱离，浑天仪之制仅存于《晋书·天文志》等记载，可见古代科学依附于个人才智与官守，缺乏制度性传承，此张衡身后之大憾。论者又当知其限：浑天说仍以地为静止之中黄，地动仪只能测震不能预报，不必以今律古，亦不可神化。张衡以一人之身兼辞章与术数，通儒之范，汉以后鲜有其匹。",
