    interpretation: "张良一生，前半段是六国贵族的抗秦史，后半段是布衣谋臣的建国史。博浪一椎不中，使他悟出个人的勇力撼动不了帝国的法度，唯有依靠人心与谋略，这才有后来「运筹帷幄」的格局。鸿门宴上留项伯、召樊哙、代献璧，步步都在刀锋边缘；荥阳借箸阻封六国，看似论古，实是保住了大一统的方向——若六国复立，楚汉之争将退回列国并立的老局。定都关中决地理根本，商山四皓决法统延续。而面对「自择齐三万户」之赏，他只请封留县，以退为进，开功臣善终的先例。留侯之名，遂成中国政治传统中谋臣智慧与知止之道的范本。",
