    interpretation: "张骞之伟大，不在于完成武帝交付的使命——联络大月氏夹击匈奴的目标终其一生未能实现，而在于他打开了一个未知世界。司马迁以「凿空」二字概括其行，最见史识：此前中原对葱岭以西几无所知，张骞之后，三十六国具载于史。十三年磨难淬炼出的，是一种国家意志的载体——持节不失，既是汉使的身份认同，也是王朝信义的象征。从深层看，张骞通西域使汉朝国防战略从被动防御转向主动经营，断匈奴右臂的目标虽由霍去病、赵破奴、郑吉等几代人接力完成，但地缘蓝图的绘制者正是张骞。他留下的不仅是一条道路，更是一种开放的眼光：一个愿意派人去看世界的帝国，才可能成为真正的世界性帝国。",
