    interpretation: "张骞通西域始于一个纯粹的军事构想——联络大月氏、断匈奴右臂，结果却远超军事范畴。两度西行，前后二十余年，带回来的不是联盟，而是西域三十六国的山川道里、户口兵制与物产风俗，使中原第一次认识葱岭以西的世界。河西四郡把郡县制推行到祁连山麓，西域都护府又将诸国纳入统辖，匈奴右臂终被切断，汉匈战争的战略格局随之改观。司马迁称其「凿空」，一语道破本质：此前中原与西域之间是地理空白，此后贯通欧亚的通道被打开，丝绸西去，良马东来，文明交汇的格局由此奠定。",
