    interpretation: "昭宣中兴之要，在因革有度。武帝晚年轮台之诏，已开改弦更张之端；霍光辅政，一遵其意，与民休息，非尽废旧法，乃宽其猛、节其用也。霍光处伊周之地，拥立两帝、废一君而不为篡，终能善始令终，固由其谨慎守节，亦因汉家法度未隳、君臣之分犹存。宣帝起自闾阎，知稼穑之艰难、闾里之善恶，亲政后以综核名实绳群下，以霸王道杂之驭天下，故吏称其职、民安其业。其治不在变法更制，而在择人慎罚、务本恤民。西域都护之设、呼韩邪之称臣，则武帝未竟之业，至昭宣而底定。汉祚由是延百数十年，后世论中兴者，辄以周宣王、汉孝宣并称，非虚誉也。",
